      currency: read('COST_CURRENCY', 'USD').toUpperCase(),
    },
    hubspot: {
      token: read('HUBSPOT_PRIVATE_APP_TOKEN'),
      sandboxPortalId: read('HUBSPOT_SANDBOX_PORTAL_ID'),
      baseUrl: read('HUBSPOT_BASE_URL', 'https://api.hubapi.com'),
      searchDelayMs: envInt(env.HUBSPOT_SEARCH_DELAY_MS, 300),
    },
    log: {
      target: envChoice(env.LOG_TARGET, ['none', 'webhook', 'google_sheets'], 'none'),
      webhookUrl: read('LOG_WEBHOOK_URL'),
      webhookSecret: read('LOG_WEBHOOK_SECRET'),
      includeContactIds: envFlag(env.LOG_INCLUDE_CONTACT_IDS, false),
      google: {
        serviceAccountJson: read('GOOGLE_SERVICE_ACCOUNT_JSON'),
        spreadsheetId: read('GOOGLE_SHEETS_SPREADSHEET_ID'),
        range: read('GOOGLE_SHEETS_RANGE', 'Hygiene Log!A1'),
      },
    },
  };
}

function validateHygieneConfig(config) {
  const errors = [];
  const warnings = [];
  const live = !config.dryRun;
  if (config.checker.provider === 'invalid') errors.push('SMTP_CHECKER_PROVIDER must be mock, zerobounce, neverbounce or custom');
  if (['zerobounce', 'neverbounce', 'custom'].includes(config.checker.provider) && isUnsetValue(config.checker.apiKey)) {
    errors.push(`SMTP_CHECKER_API_KEY is required for SMTP_CHECKER_PROVIDER=${config.checker.provider}`);
  }
  if (config.checker.provider === 'custom' && !/^https:\/\//.test(config.checker.url)) errors.push('SMTP_CHECKER_URL must be an https:// URL for the custom provider');
  if (config.audit.staleAfterDays < 30) errors.push('STALE_AFTER_DAYS must be at least 30');
  if (config.audit.intervalDays < 1) errors.push('AUDIT_INTERVAL_DAYS must be at least 1');
  if (config.policy.maxQuarantineRatio <= 0 || config.policy.maxQuarantineRatio > 1) errors.push('MAX_QUARANTINE_RATIO must be greater than 0 and at most 1');
  for (const s of config.policy.nonMarketingStatuses) if (!HYGIENE_STATUSES.includes(s)) errors.push(`NON_MARKETING_STATUSES has unknown status "${s}"`);
  if (config.log.target === 'webhook' && !/^https:\/\//.test(config.log.webhookUrl)) errors.push('LOG_WEBHOOK_URL must be an https:// URL when LOG_TARGET=webhook');
  if (config.log.target === 'google_sheets') {
    if (isUnsetValue(config.log.google.serviceAccountJson)) errors.push('GOOGLE_SERVICE_ACCOUNT_JSON is required when LOG_TARGET=google_sheets');
    if (isUnsetValue(config.log.google.spreadsheetId)) errors.push('GOOGLE_SHEETS_SPREADSHEET_ID is required when LOG_TARGET=google_sheets');
  }
  if (config.savings.monthlyCostPer1000 === 0) warnings.push('MARKETING_CONTACT_MONTHLY_COST_PER_1000 is 0: savings are reported as 0');
  if (config.log.target === 'none') warnings.push('LOG_TARGET=none: the summary is only returned, not appended anywhere');
  if (live) {
    if (isUnsetValue(config.hubspot.token)) errors.push('HUBSPOT_PRIVATE_APP_TOKEN is missing or a placeholder');
    if (config.checker.provider === 'mock') errors.push('SMTP_CHECKER_PROVIDER=mock cannot drive live HubSpot updates; set DRY_RUN=true or choose a real provider');
    if (!config.sandboxMode) warnings.push('SANDBOX_MODE=false and DRY_RUN=false: production HubSpot contacts are updated');
  }
  return { errors, warnings };
}

// ---- src/core/deliverability.js ----
/**
 * Lightweight deliverability checks.
 *
 * I don't open SMTP connections from the automation host: port 25 is blocked on
 * most clouds, RCPT probing hurts the sending IP's reputation, and many corporate
 * mail servers answer "accept all". Instead the check combines:
 *   1. local signals: syntax, disposable domains, role addresses,
 *   2. HubSpot's own bounce signals (hard bounce reason, quarantined flag, bounce count),
 *   3. an optional verification API (ZeroBounce, NeverBounce, or a custom HTTPS endpoint).
 *
 * Normalized statuses: valid | invalid | hard_bounce | disposable | role | spamtrap |
 * do_not_mail | catch_all | unknown | error
 */

const DISPOSABLE_MAIL_DOMAINS = new Set([
  '10minutemail.com', 'dispostable.com', 'emailondeck.com', 'fakeinbox.com', 'getnada.com', 'guerrillamail.com',
  'guerrillamail.net', 'maildrop.cc', 'mailinator.com', 'mailnesia.com', 'mailsac.com', 'mintemail.com', 'mohmal.com',
  'sharklasers.com', 'spam4.me', 'temp-mail.org', 'tempmail.net', 'tempr.email', 'throwawaymail.com', 'trashmail.com',
  'yopmail.com', 'yopmail.net',
]);

const ROLE_LOCAL_PARTS = new Set([
  'admin', 'administrator', 'billing', 'contact', 'enquiries', 'hello', 'help', 'hr', 'info', 'inquiries', 'jobs',
  'marketing', 'no-reply', 'noreply', 'office', 'postmaster', 'press', 'sales', 'support', 'team', 'webmaster',
]);

const MAILBOX_SYNTAX_RE = /^[a-z0-9.!#$%&'*+/=?^_`{|}~-]{1,64}@(?=.{4,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;

function mailboxParts(email) {
  const e = String(email || '').trim().toLowerCase();
  const at = e.lastIndexOf('@');
  return at > 0 ? { email: e, local: e.slice(0, at), domain: e.slice(at + 1) } : { email: e, local: '', domain: '' };
}

/** Local + HubSpot signals. Returns a definitive status, or null when an API check is still useful. */
function localDeliverabilitySignals(contactProps) {
  const { email, local, domain } = mailboxParts(contactProps.email);
  if (!email) return { status: 'invalid', source: 'local', detail: 'no email address' };
  if (!MAILBOX_SYNTAX_RE.test(email) || local.startsWith('.') || local.endsWith('.') || local.includes('..')) {
    return { status: 'invalid', source: 'local', detail: 'syntax' };
  }
  if (String(contactProps.hs_email_hard_bounce_reason_enum || '').trim()) {
    return { status: 'hard_bounce', source: 'hubspot', detail: `hard bounce: ${String(contactProps.hs_email_hard_bounce_reason_enum).slice(0, 60)}` };
  }
  if (String(contactProps.hs_email_quarantined).toLowerCase() === 'true') {
    return { status: 'hard_bounce', source: 'hubspot', detail: `HubSpot quarantined${contactProps.hs_email_quarantined_reason ? `: ${String(contactProps.hs_email_quarantined_reason).slice(0, 60)}` : ''}` };
  }
  const parts = domain.split('.');
  for (let i = 0; i < parts.length - 1; i += 1) {
    if (DISPOSABLE_MAIL_DOMAINS.has(parts.slice(i).join('.'))) return { status: 'disposable', source: 'local', detail: domain };
  }
  if (ROLE_LOCAL_PARTS.has(local.split('+')[0])) return { status: 'role', source: 'local', detail: local };
  return null;
}

/** Offline provider: deterministic rules on reserved test domains (RFC 2606). */
function mockVerify(email) {
  const { domain } = mailboxParts(email);
  if (domain.endsWith('.invalid')) return { status: 'invalid', source: 'mock', detail: 'reserved .invalid domain' };
  if (domain === 'catch-all.example') return { status: 'catch_all', source: 'mock', detail: 'mock catch-all domain' };
  if (domain === 'unknown.example') return { status: 'unknown', source: 'mock', detail: 'mock unknown domain' };
  if (domain === 'spamtrap.example') return { status: 'spamtrap', source: 'mock', detail: 'mock spam trap' };
  return { status: 'valid', source: 'mock', detail: 'mock accept' };
}

const ZEROBOUNCE_MAP = {
  valid: 'valid', invalid: 'invalid', 'catch-all': 'catch_all', unknown: 'unknown', spamtrap: 'spamtrap', abuse: 'do_not_mail', do_not_mail: 'do_not_mail',
};
const NEVERBOUNCE_MAP = { valid: 'valid', invalid: 'invalid', disposable: 'disposable', catchall: 'catch_all', unknown: 'unknown' };

async function fetchJsonWithTimeout(fetchImpl, url, init, timeoutMs) {
  const controller = typeof AbortController === 'function' ? new AbortController() : null;
  const timer = controller ? setTimeout(() => controller.abort(), timeoutMs) : null;
  try {
    const response = await fetchImpl(url, { ...init, ...(controller ? { signal: controller.signal } : {}) });
    const text = await response.text();
    return { ok: response.ok, status: response.status, body: text ? JSON.parse(text) : {} };
  } finally {
    if (timer) clearTimeout(timer);
  }
}

/** One API verification. Provider errors become status "error" (never "invalid"). */
async function apiVerify(email, { checker, fetchImpl }) {
  try {
    if (checker.provider === 'zerobounce') {
      const r = await fetchJsonWithTimeout(fetchImpl, `https://api.zerobounce.net/v2/validate?api_key=${encodeURIComponent(checker.apiKey)}&email=${encodeURIComponent(email)}&ip_address=`, { method: 'GET' }, checker.timeoutMs);
      if (!r.ok || r.body.error) return { status: 'error', source: 'zerobounce', detail: `HTTP ${r.status}` };
      const status = ZEROBOUNCE_MAP[String(r.body.status || '').toLowerCase()] || 'unknown';
      return { status: r.body.sub_status === 'role_based' && status === 'valid' ? 'role' : status, source: 'zerobounce', detail: String(r.body.sub_status || '').slice(0, 60) };
    }
    if (checker.provider === 'neverbounce') {
      const r = await fetchJsonWithTimeout(fetchImpl, `https://api.neverbounce.com/v4/single/check?key=${encodeURIComponent(checker.apiKey)}&email=${encodeURIComponent(email)}`, { method: 'GET' }, checker.timeoutMs);
      if (!r.ok || r.body.status !== 'success') return { status: 'error', source: 'neverbounce', detail: `HTTP ${r.status}` };
      return { status: NEVERBOUNCE_MAP[String(r.body.result || '').toLowerCase()] || 'unknown', source: 'neverbounce', detail: String(r.body.result || '') };
    }
    if (checker.provider === 'custom') {
      const r = await fetchJsonWithTimeout(
        fetchImpl,
        checker.url,
        { method: 'POST', headers: { 'content-type': 'application/json', authorization: `Bearer ${checker.apiKey}` }, body: JSON.stringify({ email }) },
        checker.timeoutMs,
      );
      if (!r.ok) return { status: 'error', source: 'custom', detail: `HTTP ${r.status}` };
      const status = String(r.body.status || '').toLowerCase().replace('-', '_');
      const allowed = ['valid', 'invalid', 'hard_bounce', 'disposable', 'role', 'spamtrap', 'do_not_mail', 'catch_all', 'unknown'];
      return { status: allowed.includes(status) ? status : 'unknown', source: 'custom', detail: String(r.body.detail || '').slice(0, 60) };
    }
    return mockVerify(email);
  } catch (err) {
    return { status: 'error', source: checker.provider, detail: err && err.name === 'AbortError' ? 'timeout' : 'request failed' };
  }
}

/** Runs local signals first, then the API (rate-limited and capped by MAX_VERIFICATIONS_PER_RUN). */
async function checkDeliverability(contacts, { checker, fetchImpl, sleep = (ms) => new Promise((r) => setTimeout(r, ms)) }) {
  const results = {};
  let apiCalls = 0;
  let skippedForCap = 0;
  for (const contact of contacts) {
    const local = localDeliverabilitySignals(contact.properties);
    if (local) {
      results[contact.id] = local;
      continue;
    }
    if (checker.provider === 'mock') {
      results[contact.id] = mockVerify(contact.properties.email);
      continue;
    }
    if (isUnsetValue(checker.apiKey) || apiCalls >= checker.maxVerifications) {
      results[contact.id] = { status: 'error', source: checker.provider, detail: 'verification cap reached' };
      skippedForCap += 1;
      continue;
    }
    if (apiCalls > 0 && checker.delayMs) await sleep(checker.delayMs);
    apiCalls += 1;
    results[contact.id] = await apiVerify(mailboxParts(contact.properties.email).email, { checker, fetchImpl });
  }
  return { results, apiCalls, skippedForCap };
}

// ---- src/core/hubspotContacts.js ----
/**
 * HubSpot contacts client: paged search for aging contacts and guarded batch updates.
 *
 *   DRY_RUN=true      -> batch updates are recorded and returned, never sent
 *   SANDBOX_MODE=true -> writes require a SANDBOX / DEVELOPER_TEST account type,
 *                        or the portal ID in HUBSPOT_SANDBOX_PORTAL_ID
 *   placeholder token -> offline: search returns injected fixture contacts, writes are refused
 */

const CONTACT_READ_PROPERTIES = [
  'email', 'firstname', 'lastname', 'jobtitle', 'company', 'lifecyclestage', 'hs_marketable_status',
  'lastmodifieddate', 'hs_last_sales_activity_timestamp', 'notes_last_updated', 'hs_email_last_open_date',
  'hs_email_last_click_date', 'hs_sales_email_last_replied', 'recent_conversion_date',
  'hs_email_hard_bounce_reason_enum', 'hs_email_quarantined', 'hs_email_quarantined_reason', 'hs_email_bounce',
  'list_hygiene_status', 'list_hygiene_checked_at',
];

const ENGAGEMENT_DATE_PROPERTIES = [
  'hs_last_sales_activity_timestamp', 'notes_last_updated', 'hs_email_last_open_date', 'hs_email_last_click_date',
  'hs_sales_email_last_replied', 'recent_conversion_date',
];

class HubSpotGuardError extends Error {
  constructor(code, message) {
    super(message || code);
    this.name = 'HubSpotGuardError';
    this.code = code;
  }
}

class HubSpotHttpError extends Error {
  constructor(message, status) {
    super(message);
    this.name = 'HubSpotHttpError';
    this.status = status;
    this.code = `http_${status}`;
  }
}

function buildAgingSearchBody({ cutoffMs, onlyMarketingContacts, after }) {
  const base = [{ propertyName: 'lastmodifieddate', operator: 'LT', value: String(cutoffMs) }];
  if (onlyMarketingContacts) base.push({ propertyName: 'hs_marketable_status', operator: 'EQ', value: 'true' });
  const body = {
    filterGroups: [
      { filters: [...base, { propertyName: 'hs_last_sales_activity_timestamp', operator: 'LT', value: String(cutoffMs) }] },
      { filters: [...base, { propertyName: 'hs_last_sales_activity_timestamp', operator: 'NOT_HAS_PROPERTY' }] },
    ],
    properties: CONTACT_READ_PROPERTIES,
    sorts: [{ propertyName: 'lastmodifieddate', direction: 'ASCENDING' }],
    limit: 100,
  };
  if (after) body.after = after;
  return body;
}

function createContactsClient({
  token,
  dryRun = true,
  sandboxMode = true,
  sandboxPortalId = '',
  baseUrl = 'https://api.hubapi.com',
  searchDelayMs = 300,
  fetchImpl = globalThis.fetch,
  sleep = (ms) => new Promise((r) => setTimeout(r, ms)),
  offlineContacts = [],
}) {
  const offline = isUnsetValue(token);
  const api = String(baseUrl).replace(/\/+$/, '');
  let sandboxVerdict = null;

  async function request(method, path, body) {
    if (offline) throw new HubSpotGuardError('hubspot_offline', 'HubSpot token is a placeholder; live API calls are disabled');
    for (let attempt = 0; ; attempt += 1) {
      const response = await fetchImpl(`${api}${path}`, {
        method,
        headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' },
        body: body === undefined ? undefined : JSON.stringify(body),
      });
      if ((response.status === 429 || response.status >= 500) && attempt < 4) {
        const retryAfter = Number(response.headers && response.headers.get ? response.headers.get('retry-after') : NaN);
        await sleep(Math.min(Number.isFinite(retryAfter) && retryAfter > 0 ? retryAfter * 1000 : 1000 * 2 ** attempt, 15000));
        continue;
      }
      const text = await response.text();
      if (!response.ok) {
        const err = new HubSpotHttpError(`HubSpot ${method} ${path} failed with HTTP ${response.status}`, response.status);
        err.body = text.slice(0, 500);
        throw err;
      }
      return text ? JSON.parse(text) : {};
    }
  }

  async function verifySandbox() {
    if (!sandboxVerdict) {
      sandboxVerdict = (async () => {
        const details = await request('GET', '/account-info/v3/details');
        const portalId = String(details && details.portalId !== undefined ? details.portalId : '');
        const accountType = String((details && details.accountType) || '').toUpperCase();
        if (!isUnsetValue(sandboxPortalId)) {
          if (portalId !== String(sandboxPortalId)) throw new HubSpotGuardError('sandbox_portal_mismatch', 'SANDBOX_MODE=true but the token is not for HUBSPOT_SANDBOX_PORTAL_ID');
        } else if (!['SANDBOX', 'DEVELOPER_TEST'].includes(accountType)) {
          throw new HubSpotGuardError('sandbox_account_required', `SANDBOX_MODE=true but the account type is "${accountType || 'unknown'}"`);
        }
        return { portalId, accountType };
      })();
    }
    return sandboxVerdict;
  }

  async function searchAgingContacts({ cutoffMs, onlyMarketingContacts, maxContacts }) {
    if (offline) return { contacts: offlineContacts.slice(0, maxContacts), pages: 0, truncated: offlineContacts.length > maxContacts };
    const contacts = [];
    let after;
    let pages = 0;
    do {
      if (pages > 0 && searchDelayMs) await sleep(searchDelayMs);
      const page = await request('POST', '/crm/v3/objects/contacts/search', buildAgingSearchBody({ cutoffMs, onlyMarketingContacts, after }));
      pages += 1;
      for (const c of (page && page.results) || []) contacts.push({ id: String(c.id), properties: c.properties || {} });
      after = page && page.paging && page.paging.next ? page.paging.next.after : undefined;
    } while (after && contacts.length < maxContacts && pages < 100);
    return { contacts: contacts.slice(0, maxContacts), pages, truncated: Boolean(after) || contacts.length > maxContacts };
  }

  /** inputs: [{ id, properties }]; sent in chunks of 100. */
  async function batchUpdateContacts(inputs) {
    if (!inputs.length) return { mode: 'skipped', updated: 0, batches: 0 };
    if (dryRun) return { mode: 'intercepted_dry_run', updated: 0, planned: inputs.length, batches: Math.ceil(inputs.length / 100), sample: inputs.slice(0, 3) };
    if (sandboxMode) await verifySandbox();
    let updated = 0;
    let batches = 0;
    const warnings = [];
    for (let i = 0; i < inputs.length; i += 100) {
      const chunk = inputs.slice(i, i + 100);
      try {
        await request('POST', '/crm/v3/objects/contacts/batch/update', { inputs: chunk });
      } catch (err) {
        const touchesMarketable = chunk.some((c) => 'hs_marketable_status' in c.properties);
        if (!(err instanceof HubSpotHttpError) || err.status !== 400 || !touchesMarketable) throw err;
        warnings.push('HubSpot rejected hs_marketable_status; retried without it (use the HubSpot workflow in the README)');
        await request('POST', '/crm/v3/objects/contacts/batch/update', {
          inputs: chunk.map((c) => {
            const { hs_marketable_status: _drop, ...rest } = c.properties;
            return { id: c.id, properties: rest };
          }),
        });
      }
      updated += chunk.length;
      batches += 1;
    }
    return { mode: 'written', environment: sandboxMode ? 'sandbox' : 'production', updated, batches, warnings: [...new Set(warnings)] };
  }

  return { offline, searchAgingContacts, batchUpdateContacts, verifySandbox };
}

// ---- src/core/decisions.js ----
/**
 * Audit gate, engagement filter, buyer-title check, per-contact decision,
 * HubSpot update plan, circuit breaker and savings estimate.
 */

const DAY = 24 * 3600 * 1000;

/** Rolling gate: the audit is due when `intervalDays` have passed since the last completed run. */
function isAuditDue({ lastCompletedAt, nowMs, intervalDays, force = false }) {
  if (force) return { due: true, reason: 'forced' };
  const last = Date.parse(lastCompletedAt || '');
  if (!Number.isFinite(last)) return { due: true, reason: 'first_run' };
  const daysSince = (nowMs - last) / DAY;
  return daysSince >= intervalDays
    ? { due: true, reason: 'interval_elapsed', daysSince: Math.floor(daysSince) }
    : { due: false, reason: 'not_due', daysSince: Math.floor(daysSince), nextDueAt: new Date(last + intervalDays * DAY).toISOString() };
}

function parseHubSpotTime(value) {
  if (value === undefined || value === null || value === '') return NaN;
  if (/^\d{10,13}$/.test(String(value))) return Number(String(value).length === 13 ? value : Number(value) * 1000);
  return Date.parse(String(value));
}

/** A contact counts as engaged if any engagement timestamp is newer than the cutoff. */
function recentEngagement(properties, cutoffMs, engagementProps) {
  for (const prop of engagementProps) {
    const t = parseHubSpotTime(properties[prop]);
    if (Number.isFinite(t) && t >= cutoffMs) return prop;
  }
  return null;
}

function recentlyChecked(properties, nowMs, recheckAfterDays) {
  const t = parseHubSpotTime(properties.list_hygiene_checked_at);
  return Number.isFinite(t) && nowMs - t < recheckAfterDays * DAY;
}

function matchBuyerTitle(jobTitle, titles) {
  const title = String(jobTitle || '').trim().toLowerCase();
  if (!title) return { match: 'missing', keyword: null };
  const hasWord = (kw) => new RegExp(`(?:^|[^a-z])${kw.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?:[^a-z]|$)`).test(title);
  const excluded = titles.excludedKeywords.find(hasWord);
  if (excluded) return { match: 'non_target', keyword: excluded, excluded: true };
  const target = titles.targetKeywords.find(hasWord);
  return target ? { match: 'target', keyword: target } : { match: 'non_target', keyword: null };
}

const EMAIL_STATUS_TO_HYGIENE = {
  hard_bounce: 'quarantine_bounced',
  invalid: 'quarantine_invalid',
  disposable: 'quarantine_disposable',
  spamtrap: 'quarantine_risky',
  do_not_mail: 'quarantine_risky',
};

/** Returns { status, reason, changes, nonMarketing } for one contact, or { status: null } to leave it untouched. */
function decideContact({ contact, emailCheck, titles, policy }) {
  const props = contact.properties;
  const title = matchBuyerTitle(props.jobtitle, titles);
  const exempt = policy.exemptLifecycleStages.includes(String(props.lifecyclestage || '').toLowerCase());
  let status = null;
  let reason = '';
  if (!emailCheck || emailCheck.status === 'error') {
    return { status: null, reason: `verification unavailable (${emailCheck ? emailCheck.detail : 'no result'}): left unchanged`, title, emailStatus: 'error' };
  }
  if (EMAIL_STATUS_TO_HYGIENE[emailCheck.status]) {
    status = EMAIL_STATUS_TO_HYGIENE[emailCheck.status];
    reason = `email ${emailCheck.status} (${emailCheck.source}${emailCheck.detail ? `: ${emailCheck.detail}` : ''})`;
  } else if (emailCheck.status === 'catch_all' || emailCheck.status === 'unknown') {
    status = policy.unverifiedAction === 'quarantine' ? 'quarantine_unverified' : 'flagged_unverified';
    reason = `email ${emailCheck.status}: deliverability could not be confirmed`;
  } else if (emailCheck.status === 'role') {
    status = policy.roleAddressAction === 'quarantine' ? 'quarantine_risky' : 'flagged_role_address';
    reason = `role address (${emailCheck.detail})`;
  } else if (title.match === 'missing') {
    status = titles.missingAction === 'flag' ? 'flagged_missing_title' : 'verified';
    reason = 'email valid, no job title';
  } else if (title.match === 'non_target') {
    status = titles.mismatchAction === 'quarantine' ? 'quarantine_title_mismatch' : 'flagged_title_mismatch';
    reason = `email valid, title outside buyer criteria${title.keyword ? ` (excluded: ${title.keyword})` : ''}`;
  } else {
    status = 'verified';
    reason = `email valid, buyer title (${title.keyword})`;
  }
  if (exempt && status.startsWith('quarantine_')) {
    reason = `${reason}; exempt lifecycle stage "${props.lifecyclestage}"`;
    status = 'exempt';
  }
  return {
    status,
    reason,
    title,
    emailStatus: emailCheck.status,
    nonMarketing: policy.nonMarketingStatuses.includes(status),
  };
}

function buildContactUpdate({ contactId, decision, nowIso, policy }) {
  const properties = {
    list_hygiene_status: decision.status,
    list_hygiene_reason: decision.reason.slice(0, 500),
    list_hygiene_email_status: decision.emailStatus,
    list_hygiene_title_match: decision.title.match,
    list_hygiene_checked_at: nowIso,
  };
  if (decision.nonMarketing && policy.marketingStatusWriteMode === 'property') properties.hs_marketable_status = 'false';
  return { id: String(contactId), properties };
}

/** Stops all writes when an implausibly large share of contacts would be quarantined. */
function evaluateCircuitBreaker({ processed, quarantined, policy }) {
  if (processed < policy.circuitBreakerMinSample) return { open: false, ratio: processed ? quarantined / processed : 0 };
  const ratio = quarantined / processed;
  return ratio > policy.maxQuarantineRatio
    ? { open: true, ratio, detail: `${Math.round(ratio * 100)}% of checked contacts would be quarantined (limit ${Math.round(policy.maxQuarantineRatio * 100)}%)` }
    : { open: false, ratio };
}

function estimateSavings({ nonMarketingCount, savings }) {
  const monthly = (nonMarketingCount / 1000) * savings.monthlyCostPer1000;
  return {
    contactsRemovedFromMarketing: nonMarketingCount,
    monthly: Math.round(monthly * 100) / 100,
    annual: Math.round(monthly * 12 * 100) / 100,
    currency: savings.currency,
    ratePer1000Monthly: savings.monthlyCostPer1000,
    note: 'Estimate only: HubSpot applies marketing-contact changes at the next tier update, and tiers are sold in blocks.',
  };
}

